package com.example.data

object DevotionalData {
    fun getSeedDevotionals(): List<Devotional> {
        return listOf(
            Devotional(
                title = "The Power of Beginnings",
                date = "Monday",
                scripture = "Genesis 1:1 - 'In the beginning God created the heavens and the earth.'",
                content = "Every new day, new week, or new phase of life is an opportunity for a fresh start. God is the author of creation, meaning He excels at making beautiful things out of formless voids. When your life feels empty or chaotic, remember that the Holy Spirit is ready to hover over your situation and speak light into existence. Trust Him to start something new in you today.",
                prayer = "Lord God, thank You for being the God of fresh starts. Take the chaos or empty areas of my life and build something beautiful. I trust You with my new beginning. Amen."
            ),
            Devotional(
                title = "The Perfect Shepherd",
                date = "Tuesday",
                scripture = "Psalm 23:1 - 'The Lord is my shepherd; I shall not want.'",
                content = "A shepherd provides, protects, and guides. When David wrote this psalm, he knew from personal experience that sheep are completely dependent on their shepherd. By declaring that the Lord is your Shepherd, you are declaring that you have everything you need. You don't need to fear the future or worry about provision. Lay down in His green pastures and let Him restore your weary soul today.",
                prayer = "Lord Jesus, my Shepherd, thank You for leading me beside still waters. I choose to rest in Your provision today and release all my anxieties to Your loving care. Amen."
            ),
            Devotional(
                title = "Where Wisdom Begins",
                date = "Wednesday",
                scripture = "Proverbs 3:5-6 - 'Trust in the Lord with all your heart, and lean not on your own understanding...'",
                content = "Human understanding is limited by what we can see and feel in the moment, but God sees the end from the beginning. Truly trusting God means submitting our plans, logic, and worries to Him. When we acknowledge Him in all our choices, He promises to clear the obstacles and make our paths straight. Stop trying to figure everything out on your own; lean on His infinite wisdom instead.",
                prayer = "Father, I surrender my limited understanding to Your perfect wisdom. Direct my steps and align my desires with Your heart. I trust You completely. Amen."
            ),
            Devotional(
                title = "Unconditional Love",
                date = "Thursday",
                scripture = "John 3:16 - 'For God so loved the world, that he gave his only Son...'",
                content = "God's love is not passive; it is active and sacrificial. He did not wait for the world to become perfect before loving it; He loved us in our brokenness and sent Jesus to rescue us. This love is a gift that cannot be earned, only received with a grateful heart. Let this truth anchor your identity today: you are deeply, unconditionally, and eternally loved by the Creator of the universe.",
                prayer = "Thank You, Jesus, for the ultimate sacrifice of Love. Help me to live in the security of being Your child and to reflect Your grace to those around me today. Amen."
            ),
            Devotional(
                title = "Everything Working for Good",
                date = "Friday",
                scripture = "Romans 8:28 - 'And we know that all things work together for good to them that love God...'",
                content = "This verse is not a promise that we won't experience hardship, but a guarantee that God will redeem every pain. He is a master weaver, blending the bright threads of joy and the dark threads of suffering into a grand, purposeful masterpiece. No mistake, setback, or tragedy is too great for God to turn around for your spiritual growth and His glory.",
                prayer = "Sovereign Lord, when life is confusing or painful, help me remember that You are working behind the scenes. Guide my heart to love You and trust Your redeeming power. Amen."
            ),
            Devotional(
                title = "An Everlasting Peace",
                date = "Saturday",
                scripture = "Isaiah 9:6 - 'His name shall be called... The Prince of Peace.'",
                content = "The peace Jesus offers is not merely the absence of trouble, but the presence of God in the midst of trouble. The world tries to find peace in security, finances, or comfort, but these are fragile. Jesus, the Prince of Peace, offers a steady, unshakeable calm that guards our hearts and minds regardless of our circumstances. Take a deep breath and receive His peace now.",
                prayer = "Prince of Peace, calm the storms in my mind and heart. Let Your presence guard me, and teach me to be a peacemaker in a restless world. Amen."
            ),
            Devotional(
                title = "Living in the Light",
                date = "Sunday",
                scripture = "John 1:4-5 - 'In him was life; and the life was the light of men. And the light shineth in darkness...'",
                content = "No matter how dense or heavy the darkness around us seems, it can never overcome even the smallest flicker of light. Jesus is the ultimate Light of the world, illuminating our path and banishing the shadows of shame, doubt, and fear. As you worship today, let His light shine brightly into every corner of your soul, and carry that radiance out into the world.",
                prayer = "Lord Jesus, fill me with Your life-giving light. Let Your truth guide my path and Your joy shine through me so others may see Your glory. Amen."
            )
        )
    }
}
